<div class="home-tour" data-home-tour hidden>
    <svg class="home-tour-cursor" data-tour-cursor viewBox="0 0 24 28" width="24" height="28" aria-hidden="true" focusable="false"><path d="M3 2.5 21 14l-8 .8-4.5 8.7L3 2.5Z" fill="#111" stroke="#fff" stroke-width="1.8" stroke-linejoin="round"/></svg>
    <section class="home-tour-bubble" data-tour-bubble role="region" aria-label="Quick tour of Analista">
        <div class="home-tour-heading"><span>Analista</span><button type="button" data-tour-close aria-label="Skip the tour"><span aria-hidden="true">&times;</span></button></div>
        <p class="home-tour-message" data-tour-text aria-hidden="true"></p>
        <p class="sr-only" data-tour-announcement aria-live="polite" aria-atomic="true"></p>
        <div class="home-tour-controls"><span data-tour-counter aria-hidden="true"></span><button type="button" data-tour-previous aria-label="Previous tour step">Back</button><button type="button" data-tour-pause aria-label="Pause the tour">Pause</button><button type="button" data-tour-next>Next <span aria-hidden="true">&rarr;</span></button></div>
    </section>
</div>
<div class="home-tour-replay" data-tour-replay hidden>
    <button type="button" data-tour-start><span aria-hidden="true">&#8635;</span> Take the tour again</button>
    <button type="button" data-tour-dismiss aria-label="Hide tour reminder"><span aria-hidden="true">&times;</span></button>
</div>
